     g.mouse_areas.clear();
     g.listener_masks.clear();
     g.stack_align.clear();
     g.pending_fill.clear();
     delete g.window;
     g.window = nullptr;
     delete g.engine;
     g.engine = nullptr;
     delete g.app;
     g.app = nullptr;
     g.bridge = nullptr;
     g.tick_timer = nullptr;
     g.root = nullptr;
     g.initialized = false;
