     if (!lay) {
         return;
     }
     QObject *anchors = lay->property("anchors").value<QObject *>();
     if (!anchors) {
         return;
     }
     if (!edge) {
         item->setProperty("plPad", static_cast<double>(value));
         anchors->setProperty("margins", static_cast<double>(value));
     } else {
         anchors->setProperty(edge, static_cast<double>(value));
     }
