             assert_eq!(
                 str_prop(1, "source"),
                 "file:///tmp/pathland-assets/img.png",
                 "asset-root sources resolve to the extracted directory"
             );

             // The asset root is process-global state: restore it for other tests.
             pathland_qt_layer_set_asset_root(std::ptr::null());
