     /// GRID_ROW cells are flattened into the parent Grid (spec/PRIMITIVES.md), so
     /// columns align across rows and the row itself takes no cell.
     #[test]
     fn grid_row_flattens_into_the_grid() {
         with_qt(|| unsafe {
