     #[test]
     fn control_widgets_construct_and_apply_props() {
         with_qt(|| {
             let mut view = vstack![
                 ProgressView::with(|p| {
                     p.value(0.5);
                 }),
                 Stepper::with(|s| {
                     s.value(3.0).min(0.0).max(10.0);
                 }),
                 Gauge::with(|g| {
                     g.value(4.0).min(0.0).max(10.0);
                 }),
