                 r.apply_frame(&frame);
             }
             assert_eq!(unsafe { pathland_qt_layer_render_once() }, 1);

             let sx = unsafe { pathland_qt_layer_widget_position(2, 0) };
             let sy = unsafe { pathland_qt_layer_widget_position(2, 1) };
             let sh = unsafe { pathland_qt_layer_widget_size(2, 1) };
