             // Nodes (pre-order): 1 root HStack, 2 sidebar VStack, 3 "Menu",
             // 4 Spacer, 5 content Text.
             let mut root = hstack![
                 vstack![text("Menu"), spacer()]
                     .modifiers(pathland_view::Frame::width(200.0)),
