            1,
            property_id::IS_SECURE,
            value_type::U8,
            1,
        )];
        pathland_qt_layer_apply(secure.as_ptr(), secure.len() as u32);
        assert_eq!(int_prop(1, "echoMode"), 1, "a secure field masks its value");
    });
}

