// Test hook: the children attached to a ScrollView's contentItem (a SCROLLVIEW's
// children attach there, so `widget_child_count` can't see them).
uint32_t pathland_qt_layer_scroll_content_count(uint32_t id) {
    QQuickItem *item = findWidget(id);
    if (!item) {
        return 0;
    }
    const QVariant ci = item->property("contentItem");
    if (!ci.isValid()) {
        return 0;
    }
    QQuickItem *content = ci.value<QQuickItem *>();
    return content ? static_cast<uint32_t>(content->childItems().size()) : 0;
