             let pop = [
                 Command::set_property(1, property_id::NAV_DEPTH, value_type::U32, 1),
                 Command::remove_child(1, 4),
                 Command::insert_child(1, 2, u32::MAX),
             ];
             unsafe { pathland_qt_layer_apply(pop.as_ptr(), pop.len() as u32) };
