     std::unordered_map<QQuickItem *, uint32_t> id_of;
     id_of.reserve(g.widgets.size());
     for (auto &kv : g.widgets) {
         id_of[kv.second] = kv.first;
     }
     uint32_t top = 0;
     double top_z = 0;
     bool have = false;
     for (QQuickItem *kid : p->childItems()) {
         auto it = id_of.find(kid);
