    // Record the size kind for the spec effective-fill / fill-propagation pass.
    const uint8_t kind = (value == -1.0f)
                             ? PL_SIZE_FILL
                             : (std::isfinite(value) && value > 0.0f ? PL_SIZE_FIXED
                                                                     : PL_SIZE_NONE);
    (*dimension == 'w' ? g.width_hint : g.height_hint)[id] = kind;

    if (value == -1.0f) {
