     for (auto &kv : g.widgets) {
         kv.second->setParentItem(nullptr);
         kv.second->deleteLater();
     }
     g.widgets.clear();
     g.components.clear();
     g.parents.clear();
     g.children_of.clear();
     g.nav_slots.clear();
     g.nav_stacks.clear();
     g.nav_route.clear();
     g.nav_depth.clear();
     g.nav_custom_chrome.clear();
     g.nav_pages.clear();
     g.nav_page_tags.clear();
     g.gated_ids.clear();
     g.stack_align.clear();
     g.width_hint.clear();
     g.height_hint.clear();
     g.shape_kind.clear();
     g.hit_testing.clear();
     g.offset_x.clear();
     g.offset_y.clear();
     g.listener_masks.clear();
     g.mouse_areas.clear();
     g.pending_fill.clear();
     g.media_play_state.clear();
     g.fit_queries.clear();
     g.fit_index.clear();
     g.grid_of.clear();
     g.fg_colors.clear();
     g.fg_own.clear();
     g.shadow_color.clear();
     g.shadow_radius.clear();
     g.shadow_dx.clear();
     g.shadow_dy.clear();
     g.composite.clear();
     g.node_listeners.clear();
     g.focused_id = 0;
