             assert!(
                 (pathland_qt_layer_widget_size(2, 0) - pathland_qt_layer_widget_size(1, 0)).abs() < 0.5,
                 "a horizontal divider fills the cross (width) axis"
             );
             assert!(
                 (pathland_qt_layer_widget_size(2, 1) - 2.0).abs() < 0.5,
