     // -- Navigation adapter (Phase C): hand-built command batches drive the C++
     //    page-stack reconcile by ROUTE / NAV_DEPTH / NAV_CHROME. ---------------

     fn nav_depth() -> u32 {
         unsafe { pathland_qt_layer_nav_depth(1) }
