             assert!(
                 (unsafe { pathland_qt_layer_widget_size(3, 0) } - slot_w).abs() < 1.0,
                 "the swapped-in child fills the slot's width"
             );
             assert!(
                 (unsafe { pathland_qt_layer_widget_size(3, 1) } - slot_h).abs() < 1.0,
