 // A node's WIDTH/HEIGHT size kind (spec/LAYOUT.md): absent/hug, fill, or fixed.
 // Used to derive the spec's "effectively FILL" cross-axis stretch + fill
 // propagation at frame boundaries (the diff emits props after INSERT_CHILD, so
 // this cannot be decided at insert time).
 enum SizeKind : uint8_t {
-    PL_SIZE_NONE = 0,  // absent or HUG_CONTENT (-2) -> natural size / propagate
+    PL_SIZE_NONE = 0,  // absent -> natural size / greedy-primitive / propagate
     PL_SIZE_FILL = 1,  // FILL (-1) -> expand
     PL_SIZE_FIXED = 2, // a fixed points box -> bounds the subtree
+    PL_SIZE_HUG = 3,   // HUG_CONTENT (-2) -> natural size, overrides greed
 };

 // Per-node padding state (spec/MODIFIERS.md §Layout). Tracked separately so the
 // precedence is order-independent: per-edge > PADDING > CONTENT_MARGINS.
 struct PadState {
     bool has_padding = false;
     double padding = 0.0; // PADDING (uniform)
     bool has_content = false;
     double content = 0.0; // CONTENT_MARGINS (uniform fallback)
     bool has_top = false;
     double top = 0.0;
     bool has_right = false;
     double right = 0.0;
     bool has_bottom = false;
     double bottom = 0.0;
     bool has_left = false;
     double left = 0.0;
 };

 struct LayerState {
     QGuiApplication *app = nullptr;
     QQmlEngine *engine = nullptr;
     QQuickWindow *window = nullptr;
     QQuickItem *root = nullptr; // window contentItem: parent of every top-level node
     Bridge *bridge = nullptr;
     QTimer *tick_timer = nullptr;
     bool initialized = false;

     // The renderer's rendered-output cache: id -> QML item.
     std::unordered_map<uint32_t, QQuickItem *> widgets;
     // id -> component type (for control-specific behaviour, e.g. pickers).
     std::unordered_map<uint32_t, uint16_t> components;
     // id -> parent node id (for picker model rebuilds / nav reconcile).
     std::unordered_map<uint32_t, uint32_t> parents;
     // parent -> ordered child ids (the renderer's structural mirror; drives
     // PICKER ComboBox models and the nav slot's destination lookup).
     std::unordered_map<uint32_t, std::vector<uint32_t>> children_of;
     // Navigation slots (VSTACK/HSTACK promoted to a StackView on ROUTE):
