         QStringLiteral(
             "import QtQuick 2.15\nRectangle { objectName: \"pl%1shadow\"; z: -2; "
             "color: \"transparent\"; width: parent ? parent.width : 0; "
             "height: parent ? parent.height : 0 }")
             .arg(id);
