 bool isStackComponent(uint16_t component) {
     return component == PL_COMP_VSTACK || component == PL_COMP_HSTACK ||
            component == PL_COMP_LAZY_VSTACK || component == PL_COMP_LAZY_HSTACK ||
            component == PL_COMP_PROXY_VIEW;
