         align = idx == 0 ? Qt::AlignLeft : (idx == 1 ? Qt::AlignHCenter : Qt::AlignRight);
     } else { // Row: cross axis is vertical
         align = idx == 0 ? Qt::AlignTop : (idx == 1 ? Qt::AlignVCenter : Qt::AlignBottom);
     }
