             assert_eq!(pathland_qt_layer_render_once(), 1);

             assert_eq!(pathland_qt_layer_widget_fill(3, 0), 0, "fixed width overrides greed");
             assert!((pathland_qt_layer_widget_size(3, 0) - 120.0).abs() < 1.0, "fixed width");
