             assert_eq!(unsafe { pathland_qt_layer_widget_child_count(1) }, 4);
             // node 2 = ProgressBar with the fraction applied.
             let mut buf = [0i8; 64];
             unsafe {
                 pathland_qt_layer_widget_prop_text(
                     2,
                     c"value".as_ptr(),
                     buf.as_mut_ptr(),
                     buf.len() as u32,
                 )
             };
             assert_eq!(
                 unsafe { CStr::from_ptr(buf.as_ptr()) }.to_string_lossy(),
                 "0.5"
