             // node 3 = SpinBox with the (int-cast) value applied.
             unsafe {
                 pathland_qt_layer_widget_prop_text(
                     3,
                     c"value".as_ptr(),
                     buf.as_mut_ptr(),
                     buf.len() as u32,
