 }

 // Whether the top page is sized to fill its nav container (the content-area fix).
 uint32_t pathland_qt_layer_nav_page_fills(uint32_t slot) {
     auto it = g.nav_pages.find(slot);
     if (it == g.nav_pages.end() || it->second.empty()) {
