         int audioId = m.result.mediaInputs().entrySet().iterator().next().getKey();
         dispatcher.dispatch(dev.pathland.view.transport.Event.mediaTimeUpdated(audioId, 30f));
         ProtocolFrame delta = m.sink.frame();
