package dev.pathland.view;

import dev.pathland.view.emit.Emitter;
import dev.pathland.view.emit.FrameOpcodeSink;
import dev.pathland.view.emit.MediaInput;
import dev.pathland.view.emit.RenderResult;
import dev.pathland.view.signal.Signals;
import dev.pathland.view.signal.WritableSignal;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class MediaControllerTest {

    @Test
    void playStateReportDoesNotEchoBackAsAPlaybackCommand() {
        WritableSignal<Boolean> command = Signals.signal(true);
        MediaController player = new MediaController();
        player.source("/track.mp3");
        player.playing(command);
        FrameOpcodeSink sink = new FrameOpcodeSink();
        RenderResult result = new Emitter(sink).mount(player.attach(), Environment.DEFAULT);
        int controller = result.mediaInputs().keySet().iterator().next();
        MediaInput media = result.mediaInputs().get(controller);

        long framesBefore = sink.framesProduced();
        media.onPlayStateChanged(false);

        assertEquals(framesBefore, sink.framesProduced(),
                "a play-state report is a report: it emits no PLAYBACK_STATE command");
        assertFalse(player.playingReport().get(), "the report signal is fed");
        assertTrue(command.get(), "the app's play command is untouched (the next track keeps playing)");
    }
}
```

Wait: `framesProduced()` semantics — does the mount count as a frame? Yes. `onPlayStateChanged` sets a signal not bound to any node property, so no frame. `sink.framesProduced()` unchanged. But `playingReport` is a `Signals.signal` with no effect → no frame. Good.

However, is `player.attach()` alone a valid view root? It returns a View. `Emitter.mount` works. The controller node is materialized. `result.mediaInputs()` has the controller id. Good.

Also, `assertFalse`/`assertTrue` imported.

Now, a subtlety: `player.source("/track.mp3")` is a convenience that sets a constant source. Fine.

